def generate_coeffs(limit):
    a = [0] * (limit + 1)
    b = [0] * (limit + 1)
    c = [0] * (limit + 1)

    a[0], b[0], c[0] = 1, 0, 0
    if limit >= 1:
        a[1], b[1], c[1] = 0, 1, 0
    if limit >= 2:
        a[2], b[2], c[2] = 0, 0, 1

    for i in range(2, limit):
        a_i, b_i, c_i = a[i], b[i], c[i]
        a[i+1] = 10 * c_i
        b[i+1] = a_i - c_i
        c[i+1] = b_i - c_i

    return a, b, c

LIMIT = 10
A, B, C = generate_coeffs(LIMIT)
coeffs = {}
for i in range(LIMIT + 1):
    coeffs[i] = (A[i], B[i], C[i])

def check_solution(indices, k_values, total_target=2025):
    sum_a = 0
    sum_b = 0
    sum_c = 0
    for i in indices:
        a_i, b_i, c_i = coeffs[i]
        sum_a += k_values[i] * a_i
        sum_b += k_values[i] * b_i
        sum_c += k_values[i] * c_i

    if sum_a == total_target and sum_b == 0 and sum_c == 0:
        return True
    return False

# --- Systematic Search for S=6, allowing k_i > 1, restricted to indices i <= 10 ---
S = 6
print(f"--- Systematic Search for S={S} (i <= {LIMIT}, allowing k_i > 1) ---")

indices_range = range(LIMIT + 1)

# Iterate over the number of distinct indices used, m = 1 to 6
for m in range(1, S + 1):

    for indices_tuple in combinations(indices_range, m):
        indices = list(indices_tuple)

        def generate_compositions(n, k):
            if k == 1:
                yield [n]
                return
            for i in range(1, n - k + 2):
                for tail in generate_compositions(n - i, k - 1):
                    yield [i] + tail

        for k_partition in generate_compositions(S, m):
            k_values = {indices[j]: k_partition[j] for j in range(m)}

            if check_solution(indices, k_values):
                print(f"\nSUCCESS! Found S={S} solution:")
                print(f"Indices: {indices}")
                print(f"Coefficients k_i: {k_values}")
                exit()

print("\nSearch completed. No solution found for S=6 within the constraints i <= 10 and k_i >= 1.")

